const raw = $input.first().json;
const body = raw.body && Object.keys(raw.body).length ? raw.body : raw;

const esc = s => String(s ?? '').replace(/'/g, "''");

const title = String(body.title ?? '').trim();
let urls = body.source_urls ?? body.urls ?? [];
if (typeof urls === 'string') urls = urls.split(/[\n,]/).map(s => s.trim()).filter(Boolean);
urls = (Array.isArray(urls) ? urls : []).map(u => String(u).trim()).filter(u => /^https?:\/\//i.test(u));

// 新格式：sources = [{url, title, content}]，content 为原文正文（必须带，服务器抓不了海外站点）
let srcObjs = [];
if (Array.isArray(body.sources)) {
  srcObjs = body.sources.map(s => ({
    url: String(s.url ?? s.link ?? '').trim(),
    title: String(s.title ?? '').trim(),
    content: String(s.content ?? s.full_text ?? s.text ?? '').trim()
  })).filter(s => /^https?:\/\//i.test(s.url));
}
if (srcObjs.length === 0) srcObjs = urls.map(u => ({ url: u, title: '', content: '' }));
if (urls.length === 0) urls = srcObjs.map(s => s.url);

const errors = [];
if (!title) errors.push('title 必填');
if (urls.length === 0) errors.push('sources 或 source_urls 至少 1 个 http(s) 链接（事实核查全靠它）');

const topicId = 'T' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);

const out = {
  valid: errors.length === 0,
  valid_flag: errors.length === 0 ? 'yes' : 'no',
  errors,
  topic_id: topicId,
  title,
  angle: String(body.angle ?? '').trim(),
  direction: String(body.direction ?? '').trim(),
  keywords: Array.isArray(body.keywords) ? body.keywords.join(',') : String(body.keywords ?? '').trim(),
  brief: String(body.brief ?? body.summary ?? '').trim(),
  pushed_by: String(body.pushed_by ?? body.source ?? 'manual').trim(),
  urls,
  url_count: urls.length,
  sources: srcObjs,
  title_s: esc(title),
  angle_s: esc(body.angle ?? ''),
  direction_s: esc(body.direction ?? ''),
  keywords_s: esc(Array.isArray(body.keywords) ? body.keywords.join(',') : (body.keywords ?? '')),
  brief_s: esc(body.brief ?? body.summary ?? ''),
  pushed_by_s: esc(body.pushed_by ?? body.source ?? 'manual')
};

return [{ json: out }];

